-- Model: lna_vwevent_scheduleditems__vw_event_hkey_curr
-- Description: Current active relationship for LNA_VWEVENT_SCHEDULEDITEMS using ROW_NUMBER()
-- Generated by: bv pipeline generate transform
-- Link Type: CROSS_SOURCE_LINK

WITH RANKED_RELATIONSHIPS AS (
SELECT
    l.LNA_VWEVENT_SCHEDULEDITEMS_HKEY AS LNA_VWEVENT_SCHEDULEDITEMS_HKEY,
    l.VW_EVENT_HKEY AS VW_EVENT_HKEY,
    l.SCHEDULEDITEMS_HKEY AS SCHEDULEDITEMS_HKEY,

    -- TODO: use generated tag instead of well-known name _CURRENT_ACTIVE_TIMESTAMP
    ls._CURRENT_ACTIVE_TIMESTAMP AS _CURRENT_RELATIONSHIP_TIMESTAMP, -- was ls._AIRBYTE_EXTRACTED_AT

    ROW_NUMBER() OVER (
        PARTITION BY l.VW_EVENT_HKEY -- parent hub hk
        ORDER BY ls._CURRENT_ACTIVE_TIMESTAMP DESC -- TODO: as above. Was ls._AIRBYTE_EXTRACTED_AT
    ) AS row_num

FROM {{ source('eli_dv_bv', 'lna_vwevent_scheduleditems') }} l
INNER JOIN {{ ref('las_ssc_vwevent_scheduleditems_curr') }} ls
    ON l.LNA_VWEVENT_SCHEDULEDITEMS_HKEY = ls.LNA_VWEVENT_SCHEDULEDITEMS_HKEY
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RELATIONSHIPS
WHERE row_num = 1
